import { ResponsiveLine } from "@nivo/line";
import { mockLineData as data } from "../data/mockData";
import { useTheme } from "@mui/material";
import { tokens } from "../theme";
import { useState, forwardRef, useImperativeHandle } from "react";

const LineChart = forwardRef(({ isDashboard = false }, ref) => {
  const theme = useTheme();
  const colors = tokens(theme.palette.mode);
  const [hiddenSeries, setHiddenSeries] = useState(new Set());
  
  // Filter data based on hidden series
  const filteredData = data.filter(series => !hiddenSeries.has(series.id));
  
  // Handle legend click to toggle series visibility
  const handleLegendClick = (datum) => {
    const newHiddenSeries = new Set(hiddenSeries);
    if (hiddenSeries.has(datum.id)) {
      newHiddenSeries.delete(datum.id);
    } else {
      newHiddenSeries.add(datum.id);
    }
    setHiddenSeries(newHiddenSeries);
  };
  
  // Expose reset function to parent component
  useImperativeHandle(ref, () => ({
    resetChart: () => {
      setHiddenSeries(new Set());
    }
  }));

  return (
    <ResponsiveLine
      data={filteredData}
      theme={{
        axis: {
          domain: {
            line: {
              stroke: colors.grey[100],
            },
          },
          legend: {
            text: {
              fill: colors.grey[100],
            },
          },
          ticks: {
            line: {
              stroke: colors.grey[100],
              strokeWidth: 1,
            },
            text: {
              fill: colors.grey[100],
            },
          },
        },
        legends: {
          text: {
            fill: colors.grey[100],
          },
        },
        tooltip: {
          container: {
            color: colors.grey[500],
          },
        },
      }}
      colors={isDashboard ? { datum: "color" } : { scheme: "nivo" }}
      margin={{ top: 50, right: 110, bottom: 50, left: 60 }}
      xScale={{ type: "point" }}
      yScale={{
        type: "linear",
        min: "auto",
        max: "auto",
        stacked: true,
        reverse: false,
      }}
      yFormat=" >-.2f"
      curve="catmullRom"
      axisTop={null}
      axisRight={null}
      axisBottom={{
        tickSize: 5,
        tickPadding: 5,
        tickRotation: 0,
        legend: isDashboard ? undefined : "Month",
        legendOffset: 36,
        legendPosition: "middle",
      }}
      axisLeft={{
        tickSize: 5,
        tickPadding: 5,
        tickValues: 5,
        tickRotation: 0,
        legend: isDashboard ? undefined : "Violations",
        legendOffset: -40,
        legendPosition: "middle",
      }}
      enableGridX={false}
      enableGridY={false}
      pointSize={8}
      pointColor={{ theme: "background" }}
      pointBorderWidth={2}
      pointBorderColor={{ from: "serieColor" }}
      pointLabelYOffset={-12}
      useMesh={true}
      enableCrosshair={true}
      crosshairType="cross"
      animate={true}
      motionConfig="gentle"
      legends={[
        {
          anchor: "bottom-right",
          direction: "column",
          justify: false,
          translateX: 100,
          translateY: 0,
          itemsSpacing: 2,
          itemDirection: "left-to-right",
          itemWidth: 80,
          itemHeight: 20,
          itemOpacity: (datum) => hiddenSeries.has(datum.id) ? 0.4 : 0.75,
          symbolSize: 12,
          symbolShape: "circle",
          symbolBorderColor: "rgba(0, 0, 0, .5)",
          onClick: handleLegendClick,
          effects: [
            {
              on: "hover",
              style: {
                itemBackground: colors.orangeAccent[500],
                itemOpacity: 1,
                cursor: "pointer",
              },
            },
          ],
        },
      ]}
      tooltip={({ point }) => (
        <div
          style={{
            background: colors.primary[400],
            padding: '9px 12px',
            border: `1px solid ${colors.orangeAccent[500]}`,
            borderRadius: '4px',
            color: colors.grey[100],
          }}
        >
          <strong>{point.serieId}</strong><br/>
          <strong>{point.data.xFormatted}</strong>: {point.data.yFormatted} violations
        </div>
      )}
    />
  );
});

export default LineChart;
