import { mockTransactions, mockBarData, mockPieData, mockLineData } from "../data/mockData";

// Simulate data fetching with random variations
export const fetchDashboardData = (timeRange = "24h") => {
  return new Promise((resolve) => {
    setTimeout(() => {
      // Add slight random variations to simulate real data changes
      const randomVariation = () => Math.floor(Math.random() * 5) - 2;
      
      const updatedTransactions = mockTransactions.map(t => ({
        ...t,
        cost: `${parseInt(t.cost) + randomVariation() * 50}ft`
      }));

      const updatedStats = {
        monthlyFlights: 60 + randomVariation(),
        violations2000ft: 4 + Math.max(0, randomVariation()),
        violations1000ft: 3 + Math.max(0, randomVariation()),
        violations500ft: 1 + Math.max(0, randomVariation()),
        eaglesDisturbed: 23 + randomVariation(),
        totalFlights: 847 + randomVariation() * 10
      };

      resolve({
        transactions: updatedTransactions,
        stats: updatedStats,
        barData: mockBarData,
        pieData: mockPieData,
        lineData: mockLineData,
        lastUpdated: new Date().toLocaleTimeString()
      });
    }, 800); // Simulate network delay
  });
};